def solve_cvrp(instance):
    depot = instance["depot_index"]
    customers_list = instance["customer_ids"]
    demands = instance["demands"]
    capacity = instance["capacity"]
    matrix = instance["distance_matrix"]

    def route_load(rt):
        return sum(demands[n] for n in rt)

    def route_cost(rt):
        if not rt:
            return 0
        c = matrix[depot][rt[0]] + matrix[rt[-1]][depot]
        for i in range(len(rt) - 1):
            c += matrix[rt[i]][rt[i + 1]]
        return c

    def merge_orientation(ri_rt, rj_rt, i, j):
        if not ri_rt or not rj_rt:
            return None, None, None
        if i == ri_rt[-1] and j == rj_rt[0]:
            return 0, ri_rt, rj_rt
        if i == ri_rt[0] and j == rj_rt[-1]:
            return 1, ri_rt[::-1], rj_rt[::-1]
        if i == ri_rt[-1] and j == rj_rt[-1]:
            return 2, ri_rt, rj_rt[::-1]
        if i == ri_rt[0] and j == rj_rt[0]:
            return 3, ri_rt[::-1], rj_rt
        return None, None, None

    custs = [i for i in customers_list if demands[i] <= capacity]
    routes = [[i] for i in custs]
    if not routes:
        return []

    active = [True] * len(routes)
    loads = [demands[rt[0]] for rt in routes]
    cust2route = {}
    for rid, rt in enumerate(routes):
        cust2route[rt[0]] = rid

    savings = []
    for a in custs:
        da = matrix[depot][a]
        for b in custs:
            if b == a:
                continue
            s = da + matrix[depot][b] - matrix[a][b]
            savings.append((s, a, b))
    savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    for s, i, j in savings:
        if i not in cust2route or j not in cust2route:
            continue
        ri = cust2route[i]
        rj = cust2route[j]
        if ri == rj:
            continue
        if not (active[ri] and active[rj]):
            continue
        if loads[ri] + loads[rj] > capacity:
            continue
        mode, ori_ri, ori_rj = merge_orientation(routes[ri], routes[rj], i, j)
        if mode is None:
            continue
        routes[ri] = ori_ri + ori_rj
        loads[ri] += loads[rj]
        active[rj] = False
        for node in routes[rj]:
            cust2route[node] = ri

    routes = [routes[i] for i in range(len(routes)) if active[i]]
    if not routes:
        return []

    def two_opt_on_route(rt):
        m = len(rt)
        if m < 4:
            return rt, False
        cur = route_cost(rt)
        best_improve = (m <= 28)
        best_rt = rt
        best_delta = 0.0
        for i in range(m - 1):
            for k in range(i + 1, m):
                new_rt = rt[:i] + rt[i:k + 1][::-1] + rt[k + 1:]
                delta = route_cost(new_rt) - cur
                if delta < -1e-9:
                    if not best_improve:
                        return new_rt, True
                    if best_rt is rt or delta < best_delta or (delta == best_delta and new_rt < best_rt):
                        best_delta = delta
                        best_rt = new_rt
        if best_improve and best_rt is not rt:
            return best_rt, True
        return rt, False

    # Few passes of intra-route 2-opt
    for _ in range(3):
        changed_any = False
        for idx in range(len(routes)):
            new_rt, ok = two_opt_on_route(routes[idx])
            if ok:
                routes[idx] = new_rt
                changed_any = True
        if not changed_any:
            break

    loads = [route_load(rt) for rt in routes]
    costs = [route_cost(rt) for rt in routes]

    def best_relocate(routes, loads, costs):
        rcount = len(routes)
        best = None  # (delta, ra, rb, pa, pos, node, src_after)
        for ra in range(rcount):
            rt_a = routes[ra]
            if not rt_a:
                continue
            la = loads[ra]
            cost_a_before = costs[ra]
            for pa in range(len(rt_a)):
                node = rt_a[pa]
                d = demands[node]
                if d > la:
                    continue
                src_after = rt_a[:pa] + rt_a[pa + 1:]
                la_after = la - d
                cost_a_after = route_cost(src_after)
                for rb in range(rcount):
                    if rb == ra:
                        continue
                    lb = loads[rb]
                    if lb + d > capacity:
                        continue
                    rt_b = routes[rb]
                    cost_b_before = costs[rb]
                    m = len(rt_b)
                    for pos in range(m + 1):
                        # deterministic disallow redundant (pos==pa would require same route, but rb!=ra)
                        rt_new_b = rt_b[:pos] + [node] + rt_b[pos:]
                        delta = (cost_a_after + route_cost(rt_new_b)) - (cost_a_before + cost_b_before)
                        if delta < -1e-9:
                            cand = (delta, ra, rb, pa, pos, node)
                            if best is None or cand[0] < best[0] or (cand[0] == best[0] and (cand[1], cand[3], cand[2], cand[4]) < (best[1], best[3], best[2], best[4])):
                                best = cand + (src_after,)
        if best is None:
            return False
        delta, ra, rb, pa, pos, node, src_after = best
        routes[ra] = src_after
        routes[rb] = routes[rb][:pos] + [node] + routes[rb][pos:]
        loads[ra] -= demands[node]
        loads[rb] += demands[node]
        costs[ra] = route_cost(routes[ra])
        costs[rb] = route_cost(routes[rb])
        return True

    def best_swap(routes, loads, costs):
        rcount = len(routes)
        best = None  # (delta, ra, rb, ia, ib, na, nb, new_ra, new_rb, new_load_ra, new_load_rb)
        for ra in range(rcount):
